class Solution {
public:
    int splitArray(vector<int>& nums, int k) {
        auto canSplit = [&](long long maxSum) -> bool {
            int cnt = 1;
            long long cur = 0;
            for (int x : nums) {
                if (cur + x > maxSum) {
                    cnt++;
                    cur = x;
                    if (cnt > k) return false;
                } else {
                    cur += x;
                }
            }
            return true;
        };
        long long lo = 0, hi = 0;
        for (int x : nums) {
            lo = max(lo, (long long)x);
            hi += x;
        }
        while (lo < hi) {
            long long mid = lo + (hi - lo) / 2;
            if (canSplit(mid)) hi = mid;
            else lo = mid + 1;
        }
        return (int)lo;
    }
};

