class Solution {
    public int splitArray(int[] nums, int k) {
        long lo = 0, hi = 0;
        for (int x : nums) {
            lo = Math.max(lo, x);
            hi += x;
        }
        while (lo < hi) {
            long mid = lo + (hi - lo) / 2;
            if (canSplit(nums, k, mid)) hi = mid;
            else lo = mid + 1;
        }
        return (int) lo;
    }
    private boolean canSplit(int[] nums, int k, long maxSum) {
        int cnt = 1;
        long cur = 0;
        for (int x : nums) {
            if (cur + x > maxSum) {
                cnt++;
                cur = x;
                if (cnt > k) return false;
            } else {
                cur += x;
            }
        }
        return true;
    }
}
